// Helper to generate a deterministic rough SVG path for the torn paper edge
const getPaperTornPath = (
  width: number,
  height: number,
  seed: number,
  roughness = 4,
  segmentSize = 12
) => {
  // Deterministic pseudo-random number generator
  const randomNum = (s: number) => {
    const x = Math.sin(s) * 10000;
    return x - Math.floor(x);
  };

  let points = `M 0 0`;
  const stepsX = Math.ceil(width / segmentSize);
  
  // Top Edge (with light roughness)
  for (let i = 1; i <= stepsX; i++) {
    const x = Math.min(width, i * segmentSize);
    const y = (randomNum(seed + i) - 0.5) * roughness;
    points += ` L ${x} ${y}`;
  }

  // Right Edge (slightly torn)
  const stepsY = Math.ceil(height / segmentSize);
  for (let i = 1; i <= stepsY; i++) {
    const x = width + (randomNum(seed + stepsX + i) - 0.5) * roughness;
    const y = Math.min(height, i * segmentSize);
    points += ` L ${x} ${y}`;
  }

  // Bottom Edge (torn)
  for (let i = stepsX; i >= 0; i--) {
    const x = Math.min(width, i * segmentSize);
    const y = height + (randomNum(seed + stepsX + stepsY + i) - 0.5) * roughness;
    points += ` L ${x} ${y}`;
  }

  // Left Edge (torn)
  for (let i = stepsY; i >= 0; i--) {
    const x = (randomNum(seed + stepsX * 2 + stepsY + i) - 0.5) * roughness;
    const y = Math.min(height, i * segmentSize);
    points += ` L ${x} ${y}`;
  }

  points += " Z";
  return points;
};



